SELECT 
FROM order_request
WHERE request_id = #{requestId}
  AND user_id = #{userId}

mapper.update:
UPDATE order_request
SET published_at = #{publishedAt}
WHERE request_id = #{requestId}
  AND status IN (1, 2)
  AND published_at IS NULL

mapper.select:
SELECT 
FROM order_request
WHERE status IN (0, 2)
  AND updated_at < #{updatedBefore}
ORDER BY id
LIMIT #{limit}

SELECT COUNT(*)
FROM order_request
WHERE travel_date = #{travelDate}
  AND train_id = #{trainId}
  AND status IN (0, 1, 2)
